/* ==UserStyle==
@name Anonymous Overflow Catppuccin
@namespace github.com/catppuccin/userstyles/styles/anonymous-overflow
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/anonymous-overflow
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/anonymous-overflow/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aanonymous-overflow
@description Soothing pastel theme for Anonymous Overflow
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

/* Working instances filtered from instance list: https://aohub.httpjames.space/. */
@-moz-document domain("ao.vern.cc"),
  domain("overflow.adminforge.de"),
  domain("overflow.floppa.cloud"),
  domain("overflow.hostux.net"),
  domain("ao.bloat.cat"),
  domain("ao.owo.si"),
  domain("overflow.r4fo.com"),
  domain("overflow.ducks.party"),
  domain("anonymousoverflow.privacyredirect.com"),
  domain("soflow.nerdvpn.de"),
  domain("overflow.einfachzocken.eu"),
  domain("anonymousoverflow.catsarch.com"),
  domain("overflow.darkness.services"),
  domain("anonflow.aketawi.space"),
  domain("o.iii.st"),
  domain("overflow.canine.tools") {
  @import url("https://python.catppuccin.com/pygments/catppuccin-variables.important.css");

  :root[data-theme="auto"] {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  :root[data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }

  :root[data-theme="light"] {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    --main-bg: @base;
    --text-color: @text;
    --muted-text-color: @subtext0;
    --link-color: @blue;
    --meta-bg: @surface1;
    --input-bg: @mantle;
    --input-bg-hover: @surface1;
    --divider-color: @overlay0;

    .view-input:focus {
      border-color: @surface2;
    }

    .answer-link .icon img {
      background: none;
      filter: @text-filter;
    }
    .answer-meta.accepted {
      background-color: @green;
      color: @base;

      .answer-link .icon img {
        filter: @crust-filter;
      }
    }

    .sorting img[src="/static/icons/sort.svg"] {
      filter: @subtext0-filter;
    }

    .logo {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 49 48"><circle cx="14.5" cy="33.5" r="14.5" fill="@{teal}"/><circle cx="14.5" cy="14.5" r="14.5" fill="@{text}"/><circle cx="34.5" cy="14.5" r="14.5" fill="@{teal}"/><circle cx="34.5" cy="33.5" r="14.5" fill="@{text}"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    hr {
      border-color: @overlay0;
    }

    .error {
      background-color: @red;
    }
    .error, .success {
      color: @crust;
    }
  }
}

